/* One parameter layout for the independent single and batch editors. */
const CONTROL_IDS={single:{te:'teInput',ne:'neInput',r:'rInput',teSlider:'teSlider',neSlider:'neSlider',rSlider:'rSlider',teVal:'teVal',neVal:'neVal',rVal:'rVal',error:'paramError',low:'lowW',up:'upW',charge:'maxIon',mode:'singleMode',seg:'modeSeg',flux:'intensityScale',nist:'nistIntensityControl',localFlux:'localIntensity',path:'modePath',pathBox:'broadSeg',broad:'localBroadenEnabled',broadControl:'localBroadeningControl',params:'broadenParams',widths:'localWidths',gaussian:'localGaussian',lorentz:'localLorentz',thermal:'localThermalControl',temperatureMode:'localTemperatureMode',temperature:'localTemperature',temperatureInput:'localTemperatureInput',linkedHint:'localLinkedTemperature',convention:'bConvention',grid:'bGridStep',gridControl:'bGridControl',center:'bCenter',threshold:'bMinRel',note:'broadeningNote',headless:'headless',headlessControl:'headlessControl',resample:'resample',resampleControl:'resampleControl',step:'resampleStep',comp:'compRows',sum:'sumRow',sumVal:'sumVal',add:'addEl',localError:'localCapability'},
batch:{te:'batchTe',ne:'batchNe',r:'batchR',teSlider:'batchTeSlider',neSlider:'batchNeSlider',rSlider:'batchRSlider',teVal:'batchTeVal',neVal:'batchNeVal',rVal:'batchRVal',error:'batchParamError',low:'batchLow',up:'batchUp',charge:'batchMaxIon',mode:'batchMode',seg:'batchModeSeg',flux:'batchIntensityScale',nist:'batchNistIntensity',localFlux:'batchLocalIntensity',path:'batchModePath',pathBox:'batchPathBox',broad:'batchBroadenEnabled',broadControl:'batchBroadeningControl',params:'batchBroadenParams',widths:'batchLocalWidths',gaussian:'batchGaussian',lorentz:'batchLorentz',thermal:'batchThermalControl',temperatureMode:'batchTemperatureMode',temperature:'batchTemperature',temperatureInput:'batchTemperatureInput',linkedHint:'batchLinkedTemperature',convention:'batchConvention',grid:'batchGrid',gridControl:'batchGridControl',center:'batchCenter',threshold:'batchThreshold',note:'batchBroadeningNote',headless:'batchHeadless',headlessControl:'batchHeadlessControl',resample:'batchResample',resampleControl:'batchResampleControl',step:'batchStep',comp:'batchCompRows',sum:'batchSumRow',sumVal:'batchSumVal',add:'batchAddElement',localError:'batchLocalError'}};
function parameterMarkup(scope){const id=CONTROL_IDS[scope];
 const precise=(key,label,value,min,max)=>`<label class="f" for="${id[key]}">${label}<span class="val" id="${id[key+'Val']}"></span></label><div class="param-control"><input type="range" id="${id[key+'Slider']}" min="${min}" max="${max}" step="any" value="${key==='ne'?17:value}" aria-label="${label}滑块"><input type="text" id="${id[key]}" value="${value}" inputmode="decimal"></div>`;
 return `${precise('te','电子温度 Te [eV]',1,.5,2.5)}${precise('ne','电子密度 Ne [cm⁻³]','1e17',14,18)}${precise('r','光谱分辨率 R',1000,100,5000)}<div id="${id.error}" class="local-error"></div>
 <label class="f">波长范围 [nm]</label><div class="row2"><input type="number" id="${id.low}" value="200" step="any"><input type="number" id="${id.up}" value="500" step="any"></div>
 <label class="f">最大离子电荷</label><select id="${id.charge}"><option>0</option><option>1</option><option selected>2</option></select>
 <div id="${id.nist}" hidden><label class="f">强度尺度</label><select id="${id.flux}"><option value="photon">Photon flux</option><option value="energy">Energy flux</option></select></div>
 <div id="${id.localFlux}"><label class="f">强度尺度</label><select aria-label="本地强度尺度"><option value="photon">Photon Flux</option></select></div>
 <label class="f">计算模式</label><input id="${id.mode}" type="hidden" value="local"><div class="seg" id="${id.seg}"><button type="button" data-v="local" class="on">离线本地</button><button type="button" data-v="server">在线服务器</button><button type="button" data-v="client">客户端计算</button></div>
 <label class="f">处理路径</label><div class="seg" id="${id.pathBox}"><span id="${id.path}"></span></div><div id="${id.localError}" class="local-error" role="alert" hidden></div>
 <label class="switch local-broadening-switch" id="${id.broadControl}"><input type="checkbox" id="${id.broad}"><span class="track"></span><span>展宽</span></label>
 <div id="${id.params}" class="advanced-parameters"><div id="${id.widths}" hidden><div class="row2"><div><label class="f">额外高斯FWHM [nm]</label><input type="number" id="${id.gaussian}" value="0" min="0" step="any"></div><div><label class="f">洛伦兹FWHM [nm]</label><input type="number" id="${id.lorentz}" value="0" min="0" step="any"></div></div></div>
 <div id="${id.thermal}" hidden><label class="f">热 Doppler 温度</label><select id="${id.temperatureMode}"><option value="linked">随 Te（单温度 LTE）</option><option value="manual">独立重粒子温度</option></select><div id="${id.linkedHint}" class="hint"></div><div id="${id.temperatureInput}" hidden><label class="f">重粒子温度 [K]（0关闭热展宽）</label><input type="number" id="${id.temperature}" value="0" min="0" step="any"></div></div>
 <div class="client-parameters"><label class="f">高斯约定</label><select id="${id.convention}"><option value="nist">NIST（w=λ/R）</option><option value="physics">FWHM=λ/R</option></select><div class="row2"><div><label class="f">线中心舍入位</label><input id="${id.center}" type="number" placeholder="不舍入" min="0" step="1"></div><div><label class="f">选线阈值</label><input id="${id.threshold}" type="number" value="0" min="0" step="any"></div></div></div>
 <div id="${id.gridControl}"><label class="f">采样 / 合成网格步长 [nm]</label><input type="number" id="${id.grid}" value="0.01" min=".000001" step="any"></div><div id="${id.note}" hidden></div></div>
 <div class="optional-switches"><label class="switch" id="${id.headlessControl}" hidden><input type="checkbox" id="${id.headless}" checked><span class="track"></span><span>后台抓取</span></label><label class="switch"><input type="checkbox" id="${id.resample}"><span class="track"></span><span>按需插值 / 统一网格</span></label></div>
 <div id="${id.resampleControl}" hidden><label class="f">目标网格步长 [nm]</label><input type="number" id="${id.step}" value=".01" min=".000001" step="any"></div>
 <div class="composition-editor" id="${scope==='batch'?'batchCompositionEditor':'singleCompositionEditor'}"><h3>元素配比</h3><div id="${id.comp}"></div><div class="sum-row ok" id="${id.sum}"><b id="${id.sumVal}" class="mono">100% ✓</b></div><button class="btn sm" type="button" id="${id.add}">＋ 添加元素</button></div>`;
}
document.querySelector('#singleControls').innerHTML=parameterMarkup('single');
document.querySelector('#batchControls').innerHTML=parameterMarkup('batch');
document.querySelector('#batchFixedControls').appendChild(document.querySelector('#batchCompositionEditor'));
